import java.sql.*; public class TestRunner { public static void main(String[] args) throws Exception { try (Connection c = DriverManager.getConnection("jdbc:postgresql://localhost:5432/P8Migration", "postgres", "postgres")) { System.out.println("--- ischecksumtable ---"); ResultSet rs1 = c.createStatement().executeQuery("SELECT * FROM ischecksumtable LIMIT 5"); ResultSetMetaData md1 = rs1.getMetaData(); int cc1 = md1.getColumnCount(); while(rs1.next()) { for(int i=1; i<=cc1; i++) System.out.print(md1.getColumnName(i) + "=" + rs1.getString(i) + ", "); System.out.println(); } System.out.println("--- docversion_staging ---"); ResultSet rs2 = c.createStatement().executeQuery("SELECT object_id, migration_status FROM ccol.docversion_staging LIMIT 5"); while(rs2.next()) { System.out.println("object_id=" + rs2.getString(1) + ", migration_status=" + rs2.getString(2)); } } } }
